    "Laisser vide si non applicable": "\u0627\u062A\u0631\u0643\u0647 \u0641\u0627\u0631\u063A\u064B\u0627 \u0625\u0646 \u0644\u0645 \u064A\u0646\u0637\u0628\u0642",
    "#analyse RCA": { zero: "\u0644\u0627 \u062A\u062D\u0644\u064A\u0644 RCA", one: "\u062A\u062D\u0644\u064A\u0644 RCA \u0648\u0627\u062D\u062F", two: "\u062A\u062D\u0644\u064A\u0644\u0627 RCA", few: "{n} \u062A\u062D\u0627\u0644\u064A\u0644 RCA", many: "{n} \u062A\u062D\u0644\u064A\u0644\u064B\u0627 RCA", other: "{n} \u062A\u062D\u0644\u064A\u0644 RCA" },
    "#action CAPA ouverte": { zero: "\u0644\u0627 \u0625\u062C\u0631\u0627\u0621\u0627\u062A CAPA \u0645\u0641\u062A\u0648\u062D\u0629", one: "\u0625\u062C\u0631\u0627\u0621 CAPA \u0645\u0641\u062A\u0648\u062D \u0648\u0627\u062D\u062F", two: "\u0625\u062C\u0631\u0627\u0621\u0627 CAPA \u0645\u0641\u062A\u0648\u062D\u0627\u0646", few: "{n} \u0625\u062C\u0631\u0627\u0621\u0627\u062A CAPA \u0645\u0641\u062A\u0648\u062D\u0629", many: "{n} \u0625\u062C\u0631\u0627\u0621\u064B CAPA \u0645\u0641\u062A\u0648\u062D\u064B\u0627", other: "{n} \u0625\u062C\u0631\u0627\u0621 CAPA \u0645\u0641\u062A\u0648\u062D" },
