    "#an": { zero: "\u0623\u0642\u0644 \u0645\u0646 \u0633\u0646\u0629", one: "\u0633\u0646\u0629 \u0648\u0627\u062D\u062F\u0629", two: "\u0633\u0646\u062A\u0627\u0646", few: "{n} \u0633\u0646\u0648\u0627\u062A", many: "{n} \u0633\u0646\u0629", other: "{n} \u0633\u0646\u0629" },
