    "V\xE9hicules les plus accident\xE9s": "\u0627\u0644\u0645\u0631\u0643\u0628\u0627\u062A \u0627\u0644\u0623\u0643\u062B\u0631 \u062D\u0648\u0627\u062F\u062B",
